declare(strict_types=1);
require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_once __DIR__.'/../includes/permisos.php';require_once __DIR__.'/../models/MgImportacionModel.php';require_once __DIR__.'/../models/MgBitacoraModel.php';
require_role(['administrador','coordinador_mg','auxiliar_mg']);requerir_permiso('mg.expedientes.importar');
$accion=$_GET['accion']??'form';$model=new MgImportacionModel($pdo);
if($accion==='subir'&&$_SERVER['REQUEST_METHOD']==='POST'){validar_csrf();if(empty($_FILES['archivo'])||$_FILES['archivo']['error']!==UPLOAD_ERR_OK){flash('error','Selecciona un archivo CSV válido.');redir('/controllers/mg_importar.php');}$f=$_FILES['archivo'];if($f['size']>2*1024*1024){flash('error','El CSV no puede superar 2 MB.');redir('/controllers/mg_importar.php');}$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if($ext!=='csv'){flash('error','Solo se permite la extensión .csv.');redir('/controllers/mg_importar.php');}$h=fopen($f['tmp_name'],'rb');$cab=fgetcsv($h,0,',');if(!$cab){flash('error','El CSV está vacío.');redir('/controllers/mg_importar.php');}$cab=array_map(fn($x)=>strtolower(trim((string)$x)),$cab);$req=['registro_universitario','nombres','apellidos','correo','carrera','semestre','modalidad','cohorte'];if(array_diff($req,$cab)){flash('error','Faltan columnas obligatorias: '.implode(', ',array_diff($req,$cab)));redir('/controllers/mg_importar.php');}$filas=[];while(($row=fgetcsv($h,0,','))!==false){if(count($row)===1&&trim((string)$row[0])==='')continue;$row=array_pad($row,count($cab),'');$filas[]=array_combine($cab,$row);}$res=$model->validarFilas($filas);fclose($h);$_SESSION['mg_import_preview']=['archivo'=>basename($f['name']),'filas'=>$res,'token'=>bin2hex(random_bytes(32))];redir('/controllers/mg_importar.php?accion=previsualizar');}
